-- 0130 · 리허설(fixture) 반 둘(0004)의 시간표를 닫는다 — 월·수 / 화·목 17:00 에 만나던 것이 원장님 오늘 화면에 「zz_시험_학생(학교 없음) · zz_시험_남의아이」 줄로 선다(2026-09-07 월요일 e2e 실측 — 주말에만 돌던 검사가 못 봤다: 첫 열기 조회 23 · 걷기가 엉뚱한 줄을 눌러 check-warn 까지 빨개졌다).
-- 계정·반·소속은 남기고(접근 규칙 검사가 쓴다) **만나는 날만 없앤다**(to_date 를 지난 날로). 실제 DB 에서도 같다 — 리허설 반이 원장님 명단에 서면 안 된다(대전제-12 의 결). 한 번 더 돌려도 같다.
update v2.class_schedule set to_date = '2026-03-31'
 where class_id in ('00000000-0000-4000-a000-000000000001', '00000000-0000-4000-a000-000000000002') and to_date is null;
-- 반 자체도 닫는다 — 시간표만 닫으면 일정 12 의 반 회차 카드에 「정규 17:00 · 0회 · 보강 필요」로 선다(2026-09-07 실측 — 그 카드가 처음 그려지며 숨어 있던 버그(Panel.ClassMakeup)까지 드러났다). 접근 규칙 검사(check-v2-rls)는 반의 상태를 안 본다
update v2.classes set state = 'closed'
 where id in ('00000000-0000-4000-a000-000000000001', '00000000-0000-4000-a000-000000000002') and state = 'active';
